import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    _options = [];
    _value = '';
    activeOptionIndex = 0;

    @api label;

    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = value;
        this.updateActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(value) {
        this._value = value;
        this.updateActiveIndex();
    }

    updateActiveIndex() {
        if (this._options && this._options.length > 0) {
            const index = this._options.findIndex(opt => opt.value === this._value);
            if (index !== -1) {
                this.activeOptionIndex = index;
            } else if (!this._value) {
                this.activeOptionIndex = 0;
            }
        }
    }

    get processedOptions() {
        return (this._options || []).map((option, index) => {
            const isSelected = option.value === this._value;
            return {
                ...option,
                id: `option-${option.value}`,
                ariaSelected: isSelected ? 'true' : 'false'
            };
        });
    }

    get activeOptionId() {
        if (this._options && this._options.length > 0) {
            const activeOption = this._options[this.activeOptionIndex];
            if (activeOption) {
                return `option-${activeOption.value}`;
            }
        }
        return '';
    }

    handleKeyDown(event) {
        const { key } = event;
        const len = this._options.length;
        if (len === 0) return;

        let moved = true;
        switch (key) {
            case 'ArrowDown':
                if (this.activeOptionIndex < len - 1) {
                    this.activeOptionIndex++;
                }
                break;
            case 'ArrowUp':
                if (this.activeOptionIndex > 0) {
                    this.activeOptionIndex--;
                }
                break;
            case 'Home':
                this.activeOptionIndex = 0;
                break;
            case 'End':
                this.activeOptionIndex = len - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this._options[this.activeOptionIndex].value);
                break;
            default:
                moved = false;
        }

        if (moved) {
            event.preventDefault();
        }
    }

    handleClick(event) {
        const li = event.target.closest('li');
        if (li) {
            const newValue = li.dataset.value;
            this.selectOption(newValue);
        }
    }

    selectOption(newValue) {
        const index = this._options.findIndex(opt => opt.value === newValue);
        if (index === -1) return;

        const alreadySelected = (this._value === newValue);

        this.activeOptionIndex = index;

        if (!alreadySelected) {
            this._value = newValue;
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: newValue }
            }));
        }
    }
}
