        if (keysToPrevent.includes(event.key)) {
            event.preventDefault();
        } else {
            return;
        }

        const len = this._options.length;
        if (len === 0) return;

        switch (event.key) {
            case 'ArrowDown':
                if (this.activeOptionIndex < len - 1) {
                    this.activeOptionIndex++;
                }
                break;
            case 'ArrowUp':
                if (this.activeOptionIndex > 0) {
                    this.activeOptionIndex--;
                }
                break;
            case 'Home':
                this.activeOptionIndex = 0;
                break;
            case 'End':
                this.activeOptionIndex = len - 1;
                break;
            case 'Enter':
            case ' ':
                const selectedOption = this._options[this.activeOptionIndex];
                if (selectedOption) {
                    this._selectOption(selectedOption.value);
                }
                break;
        }
    }

    handleOptionClick(event) {
        const li = event.currentTarget;
        const value = li.dataset.value;
        const index = this._options.findIndex(opt => opt.value === value);
        if (index !== -1) {
            this.activeOptionIndex = index;
            this._selectOption(value);
        }
    }

    _selectOption(value) {
        if (value !== this._value) {
            this._value = value;
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value }
            }));
        }
    }
